local TopiaryFrameMaker = {}
local PRODUCTS = {
    iron_topiary = { name = "Železni okvir za topiary", ironCost = 2, woodCost = 2, leatherCost = 1, time = 5, cost = 140, prestige = 3, happiness = 1, description = "Železni okvir za oblikovanje žive meje." },
    bronze_topiary = { name = "Bronast okvir za topiary", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 340, prestige = 5, happiness = 2, description = "Bronast okvir za bolj zapletene oblike." },
    silver_topiary = { name = "Srebrni okvir za topiary", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 820, prestige = 10, happiness = 3, description = "Srebrni okvir za plemiške vrtove." },
    gilded_topiary = { name = "Pozlačeni okvir za topiary", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1750, prestige = 19, happiness = 4, description = "Pozlačeni okvir za dvorne vrtove." },
    jewel_set_topiary = { name = "Draguljasti okvir za topiary", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 3800, prestige = 35, happiness = 6, description = "Draguljasti okvir za kraljeve vrtove." },
    royal_sovereign_topiary = { name = "Kraljevski suvereni okvir za topiary", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8200, prestige = 66, happiness = 12, description = "Suvereni okvir z biseri za krono." },
}
local BUILDINGS = {
    topiary_workshop = { name = "Topiarijska delavnica", cost = { gold = 320, wood = 175, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    topiary_house = { name = "Topiarijska hiša", cost = { gold = 1180, wood = 350, stone = 260, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_topiary_atelier = { name = "Mojstrski topiarijski atelje", cost = { gold = 2950, wood = 410, stone = 510, silver = 34, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_topiary_palace = { name = "Suverena topiarijska palača", cost = { gold = 12800, wood = 620, stone = 820, gold = 82, jewel = 19 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
TopiaryFrameMaker.ironStock = 12; TopiaryFrameMaker.bronzeStock = 10; TopiaryFrameMaker.woodStock = 14; TopiaryFrameMaker.leatherStock = 10; TopiaryFrameMaker.silverStock = 8; TopiaryFrameMaker.goldStock = 6; TopiaryFrameMaker.jewelStock = 4; TopiaryFrameMaker.pearlStock = 4
TopiaryFrameMaker.productStock = {}; TopiaryFrameMaker.buildings = {}; TopiaryFrameMaker.maker = nil; TopiaryFrameMaker.activeMaking = {}; TopiaryFrameMaker.totalProducts = 0; TopiaryFrameMaker.dayTimer = 0
function TopiaryFrameMaker.init() TopiaryFrameMaker.ironStock=12; TopiaryFrameMaker.bronzeStock=10; TopiaryFrameMaker.woodStock=14; TopiaryFrameMaker.leatherStock=10; TopiaryFrameMaker.silverStock=8; TopiaryFrameMaker.goldStock=6; TopiaryFrameMaker.jewelStock=4; TopiaryFrameMaker.pearlStock=4; TopiaryFrameMaker.productStock={}; TopiaryFrameMaker.buildings={}; TopiaryFrameMaker.maker=nil; TopiaryFrameMaker.activeMaking={}; TopiaryFrameMaker.totalProducts=0; TopiaryFrameMaker.dayTimer=0; print("[TopiaryFrameMaker] Royal Topiary Frame Maker System initialized (6 products, 4 buildings)") end
function TopiaryFrameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TopiaryFrameMaker.maker={name=n or ("Topiarist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Topiarist najet: %s (spretnost: %d)",TopiaryFrameMaker.maker.name,s),"success") end; return true end
function TopiaryFrameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TopiaryFrameMaker.build(id) local ok,e=TopiaryFrameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TopiaryFrameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TopiaryFrameMaker.getQualityBonus() local b=0; for _,bd in ipairs(TopiaryFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TopiaryFrameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TopiaryFrameMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TopiaryFrameMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TopiaryFrameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TopiaryFrameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TopiaryFrameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TopiaryFrameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TopiaryFrameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TopiaryFrameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TopiaryFrameMaker.buildings==0 then return false,"Potrebna topiarijska delavnica" end; if not TopiaryFrameMaker.maker then return false,"Potreben topiarist" end; return true end
function TopiaryFrameMaker.make(pt,qty) qty=qty or 1; local ok,e=TopiaryFrameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TopiaryFrameMaker.ironStock=TopiaryFrameMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TopiaryFrameMaker.bronzeStock=TopiaryFrameMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TopiaryFrameMaker.woodStock=TopiaryFrameMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TopiaryFrameMaker.leatherStock=TopiaryFrameMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TopiaryFrameMaker.silverStock=TopiaryFrameMaker.silverStock-d.silverCost*qty end; if d.goldCost then TopiaryFrameMaker.goldStock=TopiaryFrameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TopiaryFrameMaker.jewelStock=TopiaryFrameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TopiaryFrameMaker.pearlStock=TopiaryFrameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TopiaryFrameMaker.maker then t=math.max(1,t-math.floor(TopiaryFrameMaker.maker.skill/13)) end; table.insert(TopiaryFrameMaker.activeMaking,{id="topiary_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TopiaryFrameMaker.completeMaking(m) local q=1.0+(TopiaryFrameMaker.getQualityBonus()/100); if TopiaryFrameMaker.maker then q=q+(TopiaryFrameMaker.maker.skill/140) end; q=math.min(2.5,q); TopiaryFrameMaker.productStock[m.productType]=(TopiaryFrameMaker.productStock[m.productType] or 0)+m.quantity; TopiaryFrameMaker.totalProducts=TopiaryFrameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TopiaryFrameMaker.maker then TopiaryFrameMaker.maker.itemsMade=TopiaryFrameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TopiaryFrameMaker.maker.skill=math.min(100,TopiaryFrameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okvir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"topiary.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TopiaryFrameMaker.update(dt) if not _G.state then return end; TopiaryFrameMaker.dayTimer=TopiaryFrameMaker.dayTimer+dt; if TopiaryFrameMaker.dayTimer>=30 then TopiaryFrameMaker.dayTimer=0; for i=#TopiaryFrameMaker.activeMaking,1,-1 do local m=TopiaryFrameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TopiaryFrameMaker.completeMaking(m); table.remove(TopiaryFrameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TopiaryFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TopiaryFrameMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TopiaryFrameMaker.getStats() return {ironStock=TopiaryFrameMaker.ironStock,bronzeStock=TopiaryFrameMaker.bronzeStock,woodStock=TopiaryFrameMaker.woodStock,leatherStock=TopiaryFrameMaker.leatherStock,silverStock=TopiaryFrameMaker.silverStock,goldStock=TopiaryFrameMaker.goldStock,jewelStock=TopiaryFrameMaker.jewelStock,pearlStock=TopiaryFrameMaker.pearlStock,productStock=TopiaryFrameMaker.productStock,numBuildings=#TopiaryFrameMaker.buildings,hasMaker=TopiaryFrameMaker.maker~=nil,makerName=TopiaryFrameMaker.maker and TopiaryFrameMaker.maker.name or "—",makerSkill=TopiaryFrameMaker.maker and TopiaryFrameMaker.maker.skill or 0,activeMaking=#TopiaryFrameMaker.activeMaking,totalProducts=TopiaryFrameMaker.totalProducts} end
return TopiaryFrameMaker
